-- Persian bonus-word dictionary for Baladi?
-- Source: https://github.com/MehdiRaash/persian-words
-- Source license: MIT, Copyright (c) 2019 Mehdi Raash.
-- The list is normalized to Persian Yeh/Kaf and filtered to 2-6 character Persian words.
-- A full copy of the MIT notice is shipped in the Baladi Android project at data/dictionary/LICENSE.txt.
create table if not exists public.baladi_game_dictionary (
 word text primary key,
 source text not null default 'moein_derived_mit',
 created_at timestamptz not null default now()
);
alter table public.baladi_game_dictionary enable row level security;
revoke all on public.baladi_game_dictionary from anon, authenticated;
grant select on public.baladi_game_dictionary to service_role;
drop policy if exists baladi_dictionary_service_read on public.baladi_game_dictionary;
create policy baladi_dictionary_service_read on public.baladi_game_dictionary for select to service_role using (true);
insert into public.baladi_game_dictionary(word,source) values
